paragraph.math:
$$\begin{matrix}
        {\text{dist~}\left( \mathbf{u}\text{,~}\mathbf{v} \right)} & = & {\text{∥}\mathbf{u} - \mathbf{v}\text{∥} = \sqrt{\text{(}\mathbf{u} - \mathbf{v}\text{)} \cdot \text{(}\mathbf{u} - \mathbf{v}\text{)}}} \\
         & = & \sqrt{\left( u_{1} - v_{1} \right)^{2} + \left( u_{2} - v_{2} \right)^{2} + \left( u_{3} - v_{3} \right)^{2}}
        \end{matrix}$$

$$\begin{matrix}
        {\text{∥}\mathbf{u}\text{∥~}\text{∥}\mathbf{v}\text{∥cos~}\vartheta} & = & {\frac{1}{2}\left\lbrack \text{∥}\mathbf{u}\text{∥}^{2} + \text{∥}\mathbf{v}\text{∥}^{2} - \text{∥}\mathbf{u} - \mathbf{v}\text{∥}^{2} \right\rbrack} \\
         & = & {\frac{1}{2}\left\lbrack {u_{1}^{2} + u_{2}^{2} + v_{1}^{2} + v_{2}^{2} - \left( u_{1} - v_{1} \right)^{2} - \left( u_{2} - v_{2} \right)^{2}} \right\rbrack} \\
         & = & {u_{1}v_{1} + u_{2}v_{2}} \\
         & = & {\mathbf{u} \cdot \mathbf{v}}
        \end{matrix}$$

