$$\begin{matrix}
        \widehat{p} & = & {\frac{\left\langle g\text{,~}p_{0} \right\rangle}{\left\langle p_{0}\text{,~}p_{0} \right\rangle}p_{0} + \frac{\left\langle g\text{,~}p_{1} \right\rangle}{\left\langle p_{1}\text{,~}p_{1} \right\rangle}p_{1} + \frac{\left\langle g\text{,~}p_{2} \right\rangle}{\left\langle p_{2}\text{,~}p_{2} \right\rangle}p_{2}} \\
